#!/usr/bin/python3
"""Patch CVE-2026-9496 in the pacote archives generated by Yarn."""

from __future__ import annotations

import argparse
import hashlib
import os
from pathlib import Path
import tempfile
import zipfile


PACOTE_VERSIONS = ("21.0.1", "21.0.4")
MEMBER = "node_modules/pacote/lib/util/add-git-sha.js"
VULNERABLE = b"    return spec.rawSpec.replace(/#.*$/, '') + `#${sha}`\n"
FIXED = (
    b"    // strip the committish with indexOf/slice to avoid a regexp redos\n"
    b"    const hashIndex = spec.rawSpec.indexOf('#')\n"
    b"    const base = hashIndex === -1 ? spec.rawSpec : spec.rawSpec.slice(0, hashIndex)\n"
    b"    return `${base}#${sha}`\n"
)


def patch_archive(archive: Path) -> Path:
    """Patch one Yarn cache archive and rename it for its new checksum."""
    with zipfile.ZipFile(archive) as source:
        infos = source.infolist()
        contents = {info.filename: source.read(info) for info in infos}

    member = contents[MEMBER]
    if member.count(VULNERABLE) != 1:
        raise ValueError(f"{archive}: expected exactly one vulnerable addGitSha expression")
    contents[MEMBER] = member.replace(VULNERABLE, FIXED)

    fd, temporary_name = tempfile.mkstemp(dir=archive.parent, suffix=".zip")
    os.close(fd)
    temporary = Path(temporary_name)
    try:
        with zipfile.ZipFile(temporary, "w") as output:
            for info in infos:
                output.writestr(info, contents[info.filename])

        checksum = hashlib.sha512(temporary.read_bytes()).hexdigest()
        prefix, _old_checksum = archive.stem.rsplit("-", 1)
        destination = archive.with_name(f"{prefix}-{checksum[:10]}.zip")
        temporary.replace(destination)
        archive.unlink()
    finally:
        temporary.unlink(missing_ok=True)

    print(f"{archive.name} -> {destination.name} ({checksum})")
    return destination


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("cache_dir", type=Path)
    args = parser.parse_args()

    for version in PACOTE_VERSIONS:
        matches = list(args.cache_dir.glob(f"pacote-npm-{version}-*.zip"))
        if len(matches) != 1:
            raise ValueError(
                f"expected exactly one pacote {version} archive in {args.cache_dir}, "
                f"found {len(matches)}"
            )
        patch_archive(matches[0])


if __name__ == "__main__":
    main()
